examples.setup:
val comments = remember {
    mutableStateListOf(
        MonarchCommentThreadComment(
            id = "c1",
            author = "Priya Raman",
            body = "Should this say \"billed every quarter\" instead?",
            createdAt = 1_773_133_920_000L,
            authorSeed = "u1",
        ),
        MonarchCommentThreadComment(
            id = "c2",
            author = "Tom Becker",
            body = "Yes. Monthly billing was retired last year.",
            createdAt = 1_773_135_600_000L,
            authorSeed = "u2",
            canDelete = true,
        ),
    )
}
var resolved by remember { mutableStateOf(false) }

val now = remember { System.currentTimeMillis() }
val comments = remember {
    listOf("Can we drop the footnote?", "Agreed.", "Updated the copy.", "Legal is fine.", "Shipping tomorrow.", "Thanks all.")
        .mapIndexed { i, body -> MonarchCommentThreadComment("c$i", if (i % 2 == 0) "Lee Park" else "Tom Becker", body, now - (60 - i * 5) * 60_000L) }
}
